SELECT table_name,column_name FROM information_schema.columns WHERE table_name IN ('source_product','canonical_sale_recipe_link','canonical_recipe_definition_stocks') ORDER BY 1,ordinal_position;
SELECT to_jsonb(s) FROM source_product s WHERE superseded_at IS NULL AND source_product_id IN('20161229','21162117','23673809','19989720','22857471','12027390','23643649','23562304','17878130','12027397','17914368','22510826','20824947');
SELECT to_jsonb(s) FROM canonical_sale_recipe_link s WHERE superseded_at IS NULL AND sale_item_stock_code IN('20161229','21162117','23673809','19989720','22857471','12027390','23643649','23562304','17878130','12027397','17914368','22510826','20824947');
SELECT s.*,min(f.trading_date) first_seen,max(f.trading_date) last_seen,count(f.id) observations FROM (SELECT DISTINCT stock_code,site_number FROM source_product_sale_fact WHERE superseded_at IS NULL AND trading_date='2026-11-02' AND stock_code IN('20161229','21162117','23673809','19989720','22857471','12027390','23643649','23562304','17878130','12027397','17914368','22510826','20824947')) s JOIN source_product_sale_fact f USING(stock_code,site_number) WHERE f.superseded_at IS NULL GROUP BY 1,2 ORDER BY 1;
SELECT scope,entity_key,effective_from,sales_nature,reason FROM product_reporting_mapping WHERE entity_key IN('655','173','wastage:171:914','wastage:171:915') ORDER BY id;
SELECT d.recipe_id,d.name,to_jsonb(s) FROM canonical_recipe_definition d JOIN canonical_recipe_definition_stocks s ON s.snapshot_id=d.id WHERE d.superseded_at IS NULL AND d.recipe_id IN(655,173);
